                        lam_state <= lam_init; omg_state <= omg_init;
                        x_base <= 78;
                    end
                end
                RUN: begin
                    valid_out <= 1;
                    if (count == 33) state <= FINISH;
                    else begin
                        count <= count + 1;
                        lam_state <= lam_next; omg_state <= omg_next;
                        x_base <= x_base_next;
                    end
                end
                FINISH: begin valid_out <= 0; done <= 1; state <= IDLE; end
            endcase
        end
    end

    // --- DEBUG MONITOR ---
    always @(posedge clk) begin
        if (valid_out && count == 0) begin
            $display("[RTL DEBUG] Time=%0t Count=0 (Checking Pos 543)", $time);
            $display("  lam_state[0]=%h (Should be 1)", lam_state[0]);
            $display("  lam_state[1]=%h", lam_state[1]);
            $display("  CH0: sum_even=%h sum_odd=%h found=%b", sum_even_0, sum_odd_0, found_0);
            $display("  CH0: sum_omg=%h raw_err=%h x_loc=%h val=%h", sum_omg_0, raw_err_0, x_loc_0, error_val[0]);
        end
    end
endmodule
